using D2NG.Core.D2GS.Enums;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace D2NG.Core.ItemData;

/// <summary>
/// The price columns of the game's compiled tables: what <see cref="ItemPrice"/> needs to work out
/// the gold a vendor pays for an item. Generated by the MpqData tool next to item-affixes.json.
/// </summary>
public sealed class ItemPriceTable
{
    private Dictionary<string, BasePrice> _bases;
    private Dictionary<string, ItemTypePrice> _types;
    private Dictionary<int, AffixPrice> _prefixes;
    private Dictionary<int, AffixPrice> _suffixes;
    private Dictionary<int, StatPrice> _stats;
    private Dictionary<int, SkillPrice> _skills;
    private Dictionary<int, UniquePrice> _uniques;
    private Dictionary<(int, string), SetItemPrice> _setItems;

    public List<ItemAffixSourceFile> Sources { get; set; } = [];
    public List<ItemTypePrice> ItemTypes { get; set; } = [];
    public List<BasePrice> Bases { get; set; } = [];
    public List<AffixPrice> Prefixes { get; set; } = [];
    public List<AffixPrice> Suffixes { get; set; } = [];
    public List<StatPrice> Stats { get; set; } = [];
    public List<SkillPrice> Skills { get; set; } = [];
    public List<UniquePrice> Uniques { get; set; } = [];
    public List<SetItemPrice> SetItems { get; set; } = [];
    public List<VendorPrice> Vendors { get; set; } = [];
    public List<BookPrice> Books { get; set; } = [];

    public static ItemPriceTable Load(string path)
        => JsonSerializer.Deserialize<ItemPriceTable>(File.ReadAllText(path), SerializerOptions);

    public void Save(string path) => File.WriteAllText(path, JsonSerializer.Serialize(this, SerializerOptions));

    private static readonly JsonSerializerOptions SerializerOptions = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Converters = { new JsonStringEnumConverter() }
    };

    public BasePrice Base(string code)
        => code != null && (_bases ??= Bases.GroupBy(b => b.Code).ToDictionary(g => g.Key, g => g.First())).TryGetValue(code, out var entry) ? entry : null;

    public ItemTypePrice ItemType(string code)
        => code != null && (_types ??= ItemTypes.Where(t => !string.IsNullOrEmpty(t.Code)).GroupBy(t => t.Code).ToDictionary(g => g.Key, g => g.First())).TryGetValue(code, out var entry) ? entry : null;

    public AffixPrice Prefix(int index) => (_prefixes ??= Prefixes.ToDictionary(a => a.Index)).GetValueOrDefault(index);

    public AffixPrice Suffix(int index) => (_suffixes ??= Suffixes.ToDictionary(a => a.Index)).GetValueOrDefault(index);

    public StatPrice Stat(int id) => (_stats ??= Stats.ToDictionary(s => s.Id)).GetValueOrDefault(id);

    public SkillPrice Skill(int id) => (_skills ??= Skills.ToDictionary(s => s.Id)).GetValueOrDefault(id);

    public UniquePrice Unique(int index) => (_uniques ??= Uniques.ToDictionary(u => u.Index)).GetValueOrDefault(index);

    public SetItemPrice SetItem(int set, string code)
        => (_setItems ??= SetItems.GroupBy(i => (i.Set, i.Code)).ToDictionary(g => g.Key, g => g.First())).GetValueOrDefault((set, code));

    /// <summary>
    /// The vendor whose npc row matches the monster code's name, so "JamellaAct4" finds "jamella".
    /// Every vendor pays the same share of an item's worth and only the cap differs, so the caller
    /// falls back to any row when the vendor is unknown.
    /// </summary>
    public VendorPrice Vendor(string npcCode)
        => Vendors.FirstOrDefault(v => npcCode != null && npcCode.StartsWith(v.Name.Split(' ')[0], StringComparison.OrdinalIgnoreCase));

    /// <summary>Whether <paramref name="type"/> is <paramref name="ancestor"/> or descends from it.</summary>
    public bool IsA(string type, string ancestor)
    {
        var seen = new HashSet<string>();
        var pending = new Stack<string>();
        pending.Push(type);
        while (pending.Count > 0)
        {
            var current = pending.Pop();
            if (current == ancestor)
            {
                return true;
            }

            if (current == null || !seen.Add(current) || ItemType(current) is not { } entry)
            {
                continue;
            }

            pending.Push(entry.Equivalent1);
            pending.Push(entry.Equivalent2);
        }

        return false;
    }
}

/// <summary>The itemtypes columns that change how an item is priced.</summary>
public sealed class ItemTypePrice
{
    public string Code { get; set; }
    public string Equivalent1 { get; set; }
    public string Equivalent2 { get; set; }

    /// <summary>Arrows and bolts: their cost is per 1024 in the stack.</summary>
    public bool Quiver { get; set; }

    public bool Throwable { get; set; }
    public bool Repair { get; set; }

    /// <summary>The class whose skills the type can carry as staff mods; those skills add to the price.</summary>
    public CharacterClass? StaffMods { get; set; }

    /// <summary>Class-specific types; vendors pay a quarter for them.</summary>
    public CharacterClass? Class { get; set; }
}

/// <summary>A tome is worth its base cost plus this much for every scroll in it.</summary>
public sealed class BookPrice
{
    public string BookCode { get; set; }
    public int CostPerCharge { get; set; }
}

/// <summary>The price columns of one weapons, armor or misc row.</summary>
public sealed class BasePrice
{
    public string Code { get; set; }
    public BaseItemKind Kind { get; set; }
    public string Type { get; set; }
    public int Cost { get; set; }

    /// <summary>An armor's cost is for its best defense roll and scales down with the roll it has.</summary>
    public int MaxDefense { get; set; }

    public bool Stackable { get; set; }
    public int MaxStack { get; set; }
    public int Durability { get; set; }
    public bool NoDurability { get; set; }
}

/// <summary>A magic prefix or suffix's own price on top of what its stats are worth; nearly always zero.</summary>
public sealed class AffixPrice
{
    public int Index { get; set; }
    public string Name { get; set; }
    public int Multiply { get; set; }
    public int Add { get; set; }
}

/// <summary>
/// What a point of a stat adds to an item's worth: <see cref="Add"/> once, plus the base cost times
/// the value times <see cref="Multiply"/>/1024. <see cref="Encode"/> says how the stat carries a
/// skill: 1 a single skill priced off the skill, 2 and 3 a skill and level (on hit, charges), 4 a
/// time of day range.
/// </summary>
public sealed class StatPrice
{
    public int Id { get; set; }
    public int Add { get; set; }
    public int Multiply { get; set; }
    public int Encode { get; set; }
}

public sealed class SkillPrice
{
    public int Id { get; set; }
    public int CostMultiply { get; set; }
    public int CostAdd { get; set; }
}

/// <summary>A unique replaces all stat pricing with its own multiplier and addition.</summary>
public sealed class UniquePrice
{
    public int Index { get; set; }
    public string Name { get; set; }
    public int CostMultiply { get; set; }
    public int CostAdd { get; set; }
}

/// <summary>
/// One item of a set. 1.09's setitems has a row per set holding up to six items, and an item packet
/// names only the set, so the item is told apart by its base code.
/// </summary>
public sealed class SetItemPrice
{
    public int Set { get; set; }
    public string Code { get; set; }
    public int CostMultiply { get; set; }
    public int CostAdd { get; set; }
}

/// <summary>
/// One npc row. <see cref="BuyMultiply"/>/1024 is the share of an item's worth the vendor pays,
/// and <see cref="MaxBuy"/> caps it per difficulty.
/// </summary>
public sealed class VendorPrice
{
    public string Name { get; set; }
    public int BuyMultiply { get; set; }
    public int SellMultiply { get; set; }
    public int RepairMultiply { get; set; }
    public int[] MaxBuy { get; set; } = [];
}
